/* One tap per answer. The score is an explicitly labelled, non-validated quiz index. */
let quizAdvanceTimer=null,quizSelectionToken=0,quizLocked=false;
const quizScenes=['room','calendar','calendar','clock','clock','thoughts','thoughts','room','rhythm','room','energy','rhythm'];
function cancelQuizAdvance(){clearTimeout(quizAdvanceTimer);quizAdvanceTimer=null;quizSelectionToken++;quizLocked=false;}
function chooseQuizAnswer(raw){const value=Number(raw),step=state.quizStep;if(location.hash!=='#quiz'||quizLocked||!Number.isInteger(value)||value<0||value>=quizQuestions[step].options.length)return;
 state.answers[step]=value;quizLocked=true;const token=++quizSelectionToken;quiz();
 quizAdvanceTimer=setTimeout(()=>{if(token!==quizSelectionToken||location.hash!=='#quiz')return;quizAdvanceTimer=null;quizLocked=false;if(step===quizQuestions.length-1)location.hash='profile';else{state.quizStep=step+1;quiz();window.scrollTo({top:0,behavior:'instant'});}},220);
}
function quizOptionArt(step,i){
 if(step===2)return `<span class="qv-week" aria-hidden="true">${Array.from({length:7},(_,d)=>`<i class="${d<[1,3,5,7][i]?'awake':''}"></i>`).join('')}</span>`;
 if(step===3)return `<span class="qv-time" aria-hidden="true">${['00:30','03:00','05:30','↔'][i]}</span>`;
 if(step===4)return `<span class="qv-duration" aria-hidden="true"><i style="--fill:${[18,40,68,100][i]}%"></i></span>`;
 if(step===6)return `<span class="qv-mind" aria-hidden="true">${Array.from({length:i+1},()=>'<i></i>').join('')}</span>`;
 if(step===8){const heights=[[14,14,14,14,14],[14,19,11,15,19],[11,11,12,28,29],[13,28,10,26,17]][i];return `<span class="qv-rhythm" aria-hidden="true">${heights.map(h=>`<i style="height:${h}px"></i>`).join('')}</span>`;}
 const names=step===0?['moon','arrow','spark','sun']:step===10?['chart','sun','spark','moon']:step===11?['moon','spark','sun','book']:['moon','sun','book','spark'];return `<span class="qv-option-icon" aria-hidden="true">${icon(names[i])}</span>`;
}
function renderVisualQuiz(){const step=state.quizStep,q=quizQuestions[step],short=quizBrief[step],options=short.options||q.options,tiles=[0,2,3,6,8,10,11].includes(step);main.innerHTML=`<div class="minimal-quiz visual-quiz"><div class="mq-top"><a class="mq-brand" href="#home"><span>☾</span> SleepThrough</a><a class="mq-exit" href="#home">Exit ×</a></div><div class="mq-progress-label"><span>${q.group==='YOUR NIGHTS'?'Your nights':q.group==='YOUR MIND'?'Your mind':q.group==='YOUR RHYTHM'?'Your rhythm':'Your next step'}</span><span>${step+1} / ${quizQuestions.length}</span></div><div class="mq-progress" role="progressbar" aria-label="Quiz progress" aria-valuemin="0" aria-valuemax="${quizQuestions.length}" aria-valuenow="${step}"><i style="width:${step/quizQuestions.length*100}%"></i></div><section class="mq-question"><div class="qv-scene"><img src="assets/quiz-${quizScenes[step]}.svg" width="560" height="180" alt="" fetchpriority="high"></div><h1 tabindex="-1">${short.title}</h1><p>${short.hint||'Tap the answer that feels closest.'}</p><div class="mq-options qv-options ${tiles?'qv-tiles':'qv-rows'} qv-step-${step}" role="group" aria-label="Answer options" aria-busy="${quizLocked}">${options.map((text,i)=>`<button data-answer="${i}" aria-pressed="${state.answers[step]===i}" ${quizLocked?'disabled':''}>${quizOptionArt(step,i)}<span>${escapeHTML(text)}</span><i class="qv-check" aria-hidden="true">✓</i></button>`).join('')}</div><div class="mq-actions qv-actions"><button class="mq-back" data-action="quiz-back" ${step===0?'disabled':''}>← Back</button><span class="qv-auto-note" role="status" aria-live="polite">${quizLocked?'Selected. Moving on…':'Tap to choose · Next question opens automatically'}</span></div></section><p class="mq-note">Your experience. No perfect answers.</p></div>`;
 if(!quizLocked)requestAnimationFrame(()=>main.querySelector('.mq-question h1')?.focus({preventScroll:true}));
}
function getQuizSleepScore(answers=state.answers){const indices=[2,4,6,8];if(!indices.every(i=>Number.isInteger(answers[i])&&answers[i]>=0&&answers[i]<=3))return null;const points=[25,17,8,0],labels=['Night waking','Time awake','Mental wind-down','Routine'];const dimensions=indices.map((index,i)=>({label:labels[i],points:points[answers[index]],maximum:25}));return {value:dimensions.reduce((sum,d)=>sum+d.points,0),dimensions};}
function quizIsComplete(){return quizQuestions.every((q,i)=>Number.isInteger(state.answers[i])&&state.answers[i]>=0&&state.answers[i]<q.options.length);}
function quizScorePanel(){const score=getQuizSleepScore();if(!score||!quizIsComplete())return '';const value=score.value,delta=value===100?0:Math.min(Number(state.scoreGoal)||10,100-value),goal=value+delta,y=168-value*1.05,endY=168-goal*1.05;return `<section class="quiz-score-panel" aria-labelledby="quiz-score-title"><div class="qs-snapshot"><div class="qs-ring" style="--score:${value}%"><div><strong>${value}</strong><span>/ 100</span></div></div><div><span class="qs-label">YOUR QUIZ SNAPSHOT</span><h2 id="quiz-score-title">Your Sleep Score.</h2><p>A starting point from your answers.</p><small>Self-reported quiz index · Not a wearable measurement</small></div></div><div class="qs-goal"><div class="qs-goal-copy"><span class="qs-label">YOUR GOAL WITH SLEEPTHROUGH</span><h3>${value===100?'Keep your rhythm going.':'Make room for better nights.'}</h3><p>${value===100?'Your answers reached the top of this quiz scale. Focus on keeping the practices that fit.':'Choose a target to work towards through short, hands-on daily practices.'}</p></div><div class="qs-goal-buttons" role="group" aria-label="Choose a personal score goal">${value===100?'<span class="qs-maintain">Maintain my routine</span>':[5,10,15].map(d=>`<button data-score-goal="${d}" aria-pressed="${(Number(state.scoreGoal)||10)===d}">+${Math.min(d,100-value)} <span>${['Small step','Steady goal','Stretch goal'][[5,10,15].indexOf(d)]}</span></button>`).join('')}</div><div class="qs-chart"><svg viewBox="0 0 560 218" role="img" aria-label="Current quiz score ${value}. Your chosen goal ${goal}. An illustrative goal path, not a prediction."><defs><linearGradient id="score-goal-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--lav)" stop-opacity=".3"/><stop offset="1" stop-color="var(--lav)" stop-opacity="0"/></linearGradient></defs><path class="qs-grid" d="M38 52H522M38 108H522M38 168H522"/><path d="M45 ${y} C220 ${y},320 ${endY},515 ${endY} L515 178H45Z" fill="url(#score-goal-fill)"/><path class="qs-path" d="M45 ${y} C220 ${y},320 ${endY},515 ${endY}"/><circle cx="45" cy="${y}" r="6" fill="var(--lav)"/><circle cx="515" cy="${endY}" r="7" fill="var(--lav)"/><text x="45" y="${y-17}" text-anchor="middle">${value}</text><text x="515" y="${endY-17}" text-anchor="middle" class="qs-goal-number">${goal}</text><text x="45" y="207" class="qs-axis">Today</text><text x="515" y="207" text-anchor="end" class="qs-axis">Your chosen goal</text></svg><p>Illustrative goal path. Your target is not a forecast or a promised result.</p></div></div><div class="qs-plan-cta">${btn('Explore my 28-day plan','#plans','qs-plan-button')}</div><details class="qs-method"><summary>How is this score calculated?</summary><p>Four answers contribute equally: waking frequency, estimated time awake, a busy mind before bed, and routine consistency. Each adds 0, 8, 17 or 25 points. Higher means fewer reported difficulties on these four questions. This is a simple, unvalidated product quiz index, not a clinical assessment. Your goal is an intention you choose; it is not an expected increase from using the app.</p><div>${score.dimensions.map(d=>`<span>${d.label}<b>${d.points} / 25</b></span>`).join('')}</div></details></section>`;}
